function getSeriesSortValue(years: string) {
  let match = years.match(/\d{4}/)
  if (!match) {
    return 0
  }

  return Number.parseInt(match[0], 10)
}

export function WorkSeriesList() {
  let allSeries = getWorkSeries()

  return (
    <div>
      {allSeries
        .sort((a, b) => {
          let aYear = getSeriesSortValue(a.metadata.years)
          let bYear = getSeriesSortValue(b.metadata.years)

          if (aYear === bYear) {
            return a.metadata.title.localeCompare(b.metadata.title)
          }

